enum SyncWire {
    Request(SyncRequest),
    Response(SyncResponse),
    Followup(SyncFollowup),
    ReqHave(HaveChunk),
    RespHave(HaveChunk),
    // Appended (stable discriminants) for the whole-conversation fingerprint short-circuit.
    FpRequest(FpRequest),
    FpResponse(FpResponse),
    // Optional final custody probe. Legacy endpoints close this disposable
    // connection; ordinary reconciliation remains byte-for-byte compatible.
    DurableHaveRequest {
        conversation: ConversationId,
        event_id: EventId,
    },
    DurableHaveResponse {
        conversation: ConversationId,
        event_id: EventId,
        stored: bool,
        }
    }

    /// A newer committed effect during an active round needs one follow-up.
    /// Forget its observation so the caller can requeue the journal's latest row.
    pub(super) fn finished(&mut self, group: ConversationId) -> bool {
        self.retry_at.remove(&group);
        if self.active.remove(&group) == Some(true) {
            self.seen.remove(&group);
            true
        } else {
            false
        }
    }
}

