            nodes[local].account_devices.lock().unwrap().insert(AccountDevice {
                public: nodes[sibling].identity.public(),
                certificate: account.certify(&nodes[sibling].identity.public().ed25519_pub),
            }).unwrap();
            nodes[local].set_device_sync_category(crate::node::SyncCategory::History, true).unwrap();
            assert!(nodes[local].certified_sibling(&nodes[sibling].identity.public()));
        }
