                        }
                        tokio::time::sleep(Duration::from_millis(10)).await;
                    }
                }).await.expect("the actual member pull must retain the exact plaintext and event");
            }
            for node in &nodes {
                for proof in &proofs {
                    node.roster.lock().unwrap().update(proof, Ipv4Addr::LOCALHOST.into(), &node.user_id());
                }
            }
            // Transfer the real source's signed private custody document, not
            // a copied in-memory count or a fabricated confirmation.
            let peer = sibling.routing_peer(&source.user_id()).unwrap();
            let mut cursor = DocumentSyncCursor::optional();
            tokio::time::timeout(Duration::from_secs(30), async {
                while sibling.channel_custody_count(channel, event).unwrap() != Some(1) {
                    if let Some(at) = cursor.retry_at { tokio::time::sleep_until(at.into()).await; }
                    sibling.pull_account_documents_page(&peer, &mut cursor).await.unwrap();
                }
            }).await.expect("linked observer must receive the real source custody document");
            assert_eq!(source.channel_custody_count(channel, event).unwrap(), Some(1));
            assert_eq!(sibling.channel_custody_count(channel, event).unwrap(), Some(1));
            assert_eq!(observer.channel_custody_repair_members(channel).iter().filter_map(|member|
                observer.channel_custody_member_principal(channel, member, None)).collect::<HashSet<_>>().len(), 2);
            // The two tests differ only in which certified account device owns
            // this natural repair loop. All original events, readers and routes
            // are identical; the source runs no separate repair producer.
            repair = Some(tokio::spawn(observer.clone().run_channel_custody_recovery_loop(true)));
            tokio::time::timeout(Duration::from_secs(8), async {
                loop {
                    let changed = observer.delivery_status_notify.notified();
                    tokio::pin!(changed);
                    changed.as_mut().enable();
                    if observer.channel_custody_count(channel, event).unwrap() == Some(2) { break; }
                    changed.await;
                }
            }).await.expect("account-device repair must confirm both actual external holders of the same event");
        }).catch_unwind().await;
        if let Some(worker) = repair { stop_custody_owner(&observer, worker).await; }
        for host in hosts { host.stop().await; }
        if let Err(error) = outcome { std::panic::resume_unwind(error); }
    }

